const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await ee.data.authenticateViaPrivateKey(privateKey);
  await ee.initialize();

  // 1. Geometry & Time Definitions
  const date = '2014-01-30';
  const aodBand = 'AOD_550_Dark_Target_Deep_Blue_Combined_3km';
  const scale = 3000; // MODIS AOD is 3km resolution

  // Define points for the locations
  const newDelhi = ee.Geometry.Point(77.225, 28.6139); // Center of New Delhi
  const modinagar = ee.Geometry.Point(77.625, 28.8475); // Modinagar, Uttar Pradesh
  const greaterNoida = ee.Geometry.Point(77.5367, 28.4716); // Greater Noida, Uttar Pradesh

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('MODIS/051/MOD04_3K')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select(aodBand);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No MODIS AOD images found for January 30, 2014. Trying fallback to MODIS/061/MOD04_3K.");
    collection = ee.ImageCollection('MODIS/061/MOD04_3K') // Use Collection 6.1 if 5.1 is empty
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select(aodBand);

    if (await collection.size().getInfo() === 0) {
      console.log("No data for January 30, 2014, even with fallback collection.");
      console.log("C1");
      return;
    }
  }

  const image = collection.first();

  // Function to get AOD value for a point
  const getAodValue = async (location, name) => {
    const reducerResult = await image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: location,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    if (reducerResult === null) {
      console.log(`Warning: No valid pixels for ${name} after reducing region.`);
      return { value: null, pixelCount: 0 };
    }

    // AOD values are scaled by 1000 in this dataset
    const aod = reducerResult / 1000;

    // Get pixel count for validation
    const pixelCount = await image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: location,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    return { value: aod, pixelCount: pixelCount };
  };

  const ndAodData = await getAodValue(newDelhi, "New Delhi");
  const modinagarAodData = await getAodValue(modinagar, "Modinagar");
  const greaterNoidaAodData = await getAodValue(greaterNoida, "Greater Noida");

  // 3. Calculation & Validation
  if (ndAodData.pixelCount === 0 || modinagarAodData.pixelCount === 0 || greaterNoidaAodData.pixelCount === 0) {
    console.log("No valid pixels remain for one or more locations after processing.");
    console.log("C2");
    return;
  }

  const newDelhiAod = ndAodData.value;
  const modinagarAod = modinagarAodData.value;
  const greaterNoidaAod = greaterNoidaAodData.value;

  if (newDelhiAod === null || modinagarAod === null || greaterNoidaAod === null) {
    console.log("Calculation failed for one or more locations (AOD value is null).");
    console.log("C3");
    return;
  }

  console.log(`New Delhi AOD: ${newDelhiAod.toFixed(3)} (Pixels: ${ndAodData.pixelCount})`);
  console.log(`Modinagar AOD: ${modinagarAod.toFixed(3)} (Pixels: ${modinagarAodData.pixelCount})`);
  console.log(`Greater Noida AOD: ${greaterNoidaAod.toFixed(3)} (Pixels: ${greaterNoidaAodData.pixelCount})`);

  // Fog coverage generally correlates with higher AOD values.
  // The question asks if New Delhi shows *less* fog coverage.
  const isLessFog = newDelhiAod < modinagarAod && newDelhiAod < greaterNoidaAod;

  if (isLessFog) {
    console.log("A");
  } else {
    console.log("B");
  }
}

runAnalysis().catch(err => {
  console.error("An error occurred:", err);
  console.log("D"); // Catch all other errors
});
